<template>
  <AppFrame active="issues">
    <view v-if="issue" class="xr-content detail-page">
      <view class="detail-heading"><view><view class="back-copy">隐患管理 / 详情</view><view class="title-line"><view class="xr-page-title">{{ issue.id }}</view><view v-if="issue.major" class="xr-status xr-status-major">重大隐患</view></view></view><view class="detail-actions"><button class="xr-btn xr-btn-secondary" @click="back">返回列表</button><button v-if="canAssign && issue.status==='待交办'" class="xr-btn xr-btn-primary" @click="assign">安监交办</button><button v-else-if="canReview" class="xr-btn xr-btn-primary" @click="review">复核闭环</button></view></view>
      <view class="detail-grid">
        <view class="xr-card information-card"><view class="xr-section-title">隐患信息</view><view class="detail-photo"><image v-if="issue.attachments&&issue.attachments.length" :src="issue.attachments[0]" mode="aspectFill"/><view v-else class="photo-empty"><text>!</text><text>等待现场图片</text></view></view><view class="description-label">隐患说明</view><view class="description">{{ issue.description }}</view><view class="info-grid"><view><text>现场位置</text><strong>{{ issue.location || '未标注' }}</strong></view><view><text>上报人员</text><strong>{{ issue.reporter }}</strong></view><view><text>责任部门</text><strong>{{ issue.assigneeDept || '待交办' }}</strong></view><view><text>整改期限</text><strong :class="{danger:issue.status==='已逾期'}">{{ issue.deadline }}</strong></view></view></view>
        <view class="side-column"><view class="xr-card audit-card"><view class="audit-heading"><view class="xr-section-title">审计时间线</view><text>⌄</text></view><view class="audit-list"><view v-for="row in issue.audit" :key="row.action+row.time" class="audit-row"><view class="audit-dot" :class="{danger:row.action.includes('退回')||row.action.includes('上报')}"/><view><view class="audit-name">{{ row.action }}</view><view class="audit-time">{{ row.actor }} · {{ row.time }}</view><view class="audit-note">{{ row.note }}</view></view></view></view></view>
          <view v-if="canRectify" class="xr-card rectification-card"><view class="xr-section-title">提交整改佐证</view><view class="xr-caption">请上传整改说明与现场佐证，提交后等待安监复核。</view><textarea v-model="rectification.note" class="xr-textarea" placeholder="填写整改措施、现场情况和无法完成的原因"/><view class="evidence-row"><view v-for="file in rectification.attachments" :key="file" class="evidence-image"><image :src="file" mode="aspectFill"/></view><view class="evidence-image add-evidence" @click="addPhotos">＋<text>照片</text></view></view><button class="xr-btn xr-btn-primary rectify-submit" :disabled="!rectification.note" @click="submitRectification">提交复核</button></view>
          <view v-if="issue.rectification" class="xr-card evidence-card"><view class="xr-section-title">整改材料</view><view class="evidence-note">{{ issue.rectification.note }}</view><view class="xr-caption">市场营销部提交于 {{ issue.rectification.submittedAt }}</view></view>
          <view v-if="!canAssign&&!canRectify&&!canReview" class="xr-card readonly-card"><view class="xr-section-title">只读查看</view><view class="xr-caption">当前账号无权处理该事项，可查看授权范围内的闭环进度与审计记录。</view></view>
        </view>
      </view>
    </view>
    <view v-else class="xr-content xr-empty">未找到该隐患记录</view>
  </AppFrame>
</template>

<script setup>
import { computed, reactive } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppFrame from '../../components/AppFrame.vue'
import { demoStore } from '../../stores/demo'
import { chooseEvidenceImages } from '../../services/platform'
let id=''
const issue=computed(()=>demoStore.issues.find((item)=>item.id===id))
const rectification=reactive({note:'',attachments:[]})
const canAssign=computed(()=>demoStore.can('issue-assign',issue.value))
const canRectify=computed(()=>demoStore.can('issue-rectify',issue.value))
const canReview=computed(()=>demoStore.can('issue-review',issue.value))
onLoad((options)=>{id=options.id})
function back(){uni.navigateBack({delta:1,fail:()=>uni.switchTab({url:'/pages/index/index'})})} function assign(){uni.navigateTo({url:`/pages/issue/assign?id=${id}`})} function review(){uni.navigateTo({url:`/pages/issue/review?id=${id}`})}
async function addPhotos(){try{const result=await chooseEvidenceImages();rectification.attachments.push(...result.tempFilePaths)}catch{}}
function submitRectification(){demoStore.submitRectification(id,rectification);uni.showToast({title:'整改材料已提交',icon:'success'})}
</script>

